def sum_nested_list(nested_list):
    """
    Recursively calculates the sum of all numbers within a nested list.

    Args:
        nested_list: A potentially deeply nested list containing numbers and other lists.

    Returns:
        The sum of all numbers in the nested list, as a float if any float is present,
        otherwise as an integer.
    """
    total = 0.0
    for element in nested_list:
        if isinstance(element, (int, float)):
            total += element
        elif isinstance(element, list):
            total += sum_nested_list(element)
    return total

if __name__ == "__main__":
    input_str = input()
    try:
        nested_list = eval(input_str)
        if isinstance(nested_list, list):
            result = sum_nested_list(nested_list)
            print(result)
        else:
            print("Invalid input: Input must be a list.")
    except (SyntaxError, NameError, TypeError):
        print("Invalid input: Please provide a valid Python list expression.")
