        self.data = data
        self.next = None
        self.prev = None

class Stack:
    def __init__(self):
        self.head = None

    def push(self, x):
        new_node = Node(x)
        new_node.next = self.head
        if self.head:
            self.head.prev = new_node
        self.head = new_node

    def pop(self):
        if not self.head:
            print("Stack Underflow")
            return

        print(self.head.data)
        self.head = self.head.next
        if self.head:
            self.head.prev = None

    def peek(self):
        if not self.head:
            print("Stack Underflow")
            return

        print(self.head.data)

    def is_empty(self):
        print("True" if not self.head else "False")

